-- 015_reference_foods: shared, read-only reference values (unpackaged foods, BLS 4.0) and piece weights (D-170).
-- 1) reference_foods holds the curated list for all users; a user's copy is created on first use (adopt).
-- 2) foods.piece_weight: grams/millilitres of one piece, enables the unit "Stück" on a g/ml basis.
-- 3) foods.reference_food_id links a copy to its reference; the start milks are linked to theirs.
-- No existing row is changed except the start milks (link + piece weight stay NULL for milk).

CREATE TABLE reference_foods (
    id SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    name VARCHAR(120) NOT NULL,
    category ENUM('snacks', 'dairy', 'bread', 'produce', 'drinks', 'basics', 'sauces', 'supplements', 'meals')
        NOT NULL,
    basis ENUM('per_100g', 'per_100ml') NOT NULL,
    kcal DECIMAL(6,1) NOT NULL,
    protein DECIMAL(5,1) NOT NULL,
    carbs DECIMAL(5,1) NOT NULL,
    sugar DECIMAL(5,1) NOT NULL,
    fat DECIMAL(5,1) NOT NULL,
    piece_weight DECIMAL(6,1) NULL COMMENT 'g or ml of one piece',
    source VARCHAR(255) NOT NULL COMMENT 'values and piece weight, e.g. BLS 4.0 code',
    sort SMALLINT UNSIGNED NOT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uq_reference_foods_name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ALTER TABLE foods
    ADD COLUMN piece_weight DECIMAL(6,1) NULL COMMENT 'g or ml of one piece (unit Stück on a g/ml basis)'
        AFTER package_amount,
    ADD COLUMN reference_food_id SMALLINT UNSIGNED NULL COMMENT 'copy of a shared reference value' AFTER system_key,
    ADD UNIQUE KEY uq_foods_user_reference (user_id, reference_food_id),
    ADD CONSTRAINT fk_foods_reference FOREIGN KEY (reference_food_id) REFERENCES reference_foods (id)
        ON DELETE SET NULL;

-- Values: BLS 4.0 (Max Rubner-Institut 2025, CC BY 4.0, DOI 10.25826/Data20251217-134202-0) incl. errata.
-- Piece weights: USDA FoodData Central portions or documented estimates (see source).

UPDATE foods f JOIN reference_foods r ON r.name = f.name
   SET f.reference_food_id = r.id
 WHERE f.system_key IS NOT NULL AND f.reference_food_id IS NULL;

